def _canonical_ruleset_sha256() -> str:
    raw = json.dumps(RULESET_SPEC, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _normalize_text(value: Any) -> str:
    return str(value or "").replace("\r\n", "\n").replace("\r", "\n")


def _ical_property_values(items: list[Any], property_name: str) -> list[str]:
    """Extract exact unfolded iCalendar property values, excluding prose occurrences."""
    expected_name = property_name.upper()
    values: list[str] = []
    for item in items:
        text = _normalize_text(item)
        unfolded = re.sub(r"\n[ \t]", "", text)
        for line in unfolded.split("\n"):
            if ":" not in line:
                continue
            raw_name, raw_value = line.split(":", 1)
            name = raw_name.split(";", 1)[0].strip().upper()
            if name == expected_name:
                values.append(raw_value.strip().upper())
    return values


def _weekly_every_week(items: list[Any]) -> tuple[bool, list[str]]:
    values = _ical_property_values(items, "RRULE")
    if len(items) != 1 or len(values) != 1:
        return False, values
    parts: dict[str, str] = {}
    for token in values[0].split(";"):
        if "=" not in token:
            return False, values
        key, value = token.split("=", 1)
        key = key.strip().upper()
        value = value.strip().upper()
        if not key or not value or key in parts:
            return False, values
        parts[key] = value
    # Thunderbird serialises standard weekly parts (BYDAY, WKST, UNTIL, COUNT)
    # for a Weekly event; the task only requires repeating every week. Accept
    # them while pinning FREQ=WEEKLY, INTERVAL=1 and a single weekday BYDAY.
    weekdays = {"MO", "TU", "WE", "TH", "FR", "SA", "SU"}
    allowed = {"FREQ", "INTERVAL", "BYDAY", "WKST", "UNTIL", "COUNT"}
    passed = (
        set(parts) <= allowed
        and parts.get("FREQ") == "WEEKLY"
        and parts.get("INTERVAL", "1") == "1"
    )
    if passed and "BYDAY" in parts and parts["BYDAY"] not in weekdays:
        passed = False
    if passed and "WKST" in parts and parts["WKST"] not in weekdays:
        passed = False
    return passed, values


